"""Render the visual portfolio with progressive, accessible interactions."""
import html
import datetime as dt
from detail_views import record_anchor, render_details
from validate import profile_record
from research_reach import load_reach, render_reach
from leadership import load_leadership, render_engagements, render_feedback
from case_studies import render_cases
from spotlight import load_spotlight, render_quotes, render_awards, render_forums, render_library, image_link

def e(value):return html.escape(str(value),quote=True)
def picture(item, cls='', eager=False):
    loading='fetchpriority="high"' if eager else 'loading="lazy"'
    return f'<img class="{e(cls)}" src="{e(item["path"])}" alt="{e(item["alt"])}" width="{item["width"]}" height="{item["height"]}" {loading}>'
def media_picture(item,cls='',eager=False):
    return picture({'path':item['image'],**{k:item[k] for k in ['alt','width','height']}},cls,eager)
def viewer_link(url,title,caption,kind='image',video_id=''):
    return f'href="{e(url)}" data-viewer="{kind}" data-title="{e(title)}" data-caption="{e(caption)}" data-video-id="{e(video_id)}"'

def render(p,media,s,pubs,downloads=()):
    spotlight=load_spotlight(p)
    leadership=load_leadership(p)
    reach=load_reach();metric_date=dt.date.fromisoformat(reach['as_of']).strftime('%d %b %Y').lstrip('0');photos_by_id={m['id']:m for m in media};panel=photos_by_id['iea-panel']
    cases=render_cases(s['cases'],p,photos_by_id,downloads)
    credentials=''.join(f'<article class="credential"><p class="eyebrow">{e(x["kicker"])}</p><h3>{e(x["title"])}</h3><p>{e(x["detail"])}</p><a href="{e(x["url"])}" aria-label="View details: {e(x["title"])}">View details ↗</a></article>' for x in s['credentials'])
    certifications=''.join(f'<li><a href="profile.html#{record_anchor("certifications",x["title"])}">{e(x["title"])}</a><span>{e(x["organization"])} · {e(x["date"])}</span></li>' for x in p['certifications'] if x['title'] in s['featured_certifications'])
    appearances=''
    for x in s['appearances']:
        video=reach['videos'].get(x['id']);category='watch' if video else 'recognition' if x['id'] in ['forbes-profile','hull-feature'] else 'read'
        attrs=viewer_link(x['url'],x['title'],x['format']+' · '+x['date'],video['provider'],video.get('id','')) if video else f'href="{e(x["url"])}"'
        if x['image']['path']:
            visual=f'<a class="appearance-image" {attrs}>{picture(x["image"])}<span class="media-action">{"▶ Watch" if video else "Explore ↗"}</span></a>'
        else:
            publisher=x['format'].split('·')[-1].strip()
            visual=f'<a class="editorial-cover cover-{e(x["id"])}" {attrs}><span>{e(publisher)}</span><strong>{"▶" if video else "↗"}</strong><small>{"Watch the film" if video else "Read the story"}</small></a>'
        extra=''.join(f'<a href="{e(link["url"])}">{e(link["title"])} ↗</a>' for link in x['extra'])
        appearances+=f'<article class="appearance with-image" id="{e(x["id"])}" data-media-category="{category}">{visual}<div class="appearance-copy"><p class="eyebrow">{e(x["format"])}</p><h3>{e(x["title"])}</h3><p class="date">{e(x["date"])}</p><p>{e(x["summary"])}</p><a class="text-link" {attrs}>{e(x["label"])} ↗</a><div class="extra-links">{extra}</div></div></article>'
    def credit(m):
        return '<span class="photo-credit">From my personal archive</span>' if m.get('source_kind')=='user-provided' else f'<a class="text-link" href="{e(m["source_url"])}">Original post / source ↗</a>'
    photos=''.join(f'''<figure class="gallery-photo photo-{e(m['id'])}"><a class="gallery-image" {viewer_link(m['image'],m['title'],m['caption'])}>{media_picture(m)}<span class="enlarge">View photo ↗</span></a><figcaption><p class="eyebrow">{e(m['date'])}</p><h3>{e(m['title'])}</h3><p>{e(m['caption'])}</p>{credit(m)}</figcaption></figure>''' for m in media if m['id']!='ktp-certificate' and m.get('gallery',True))
    impacts=''.join(f'<article><strong>{e(x["value"])}</strong><h3>{e(x["label"])}</h3><details class="metric-detail"><summary>Context & contribution</summary><p>{e(x["detail"])}</p></details></article>' for x in p['impact'])
    chips=''.join(f'<span>{e(x)}</span>' for x in p['focus']);book=s['book'];publication_map={x['title']:x for x in p['publications']};selected=pubs([publication_map[t] for t in s['featured_publications']])
    return f'''
<section class="visual-hero leadership-hero wrap" id="about"><div class="hero-copy"><p class="eyebrow">Enterprise AI · Strategy · Products · Leadership</p><p class="hero-name">{e(p['name'])}</p><h1>Leading AI from<br>strategy to<br><em>enterprise value.</em></h1><p class="lede">I lead AI solution development for global enterprises, bringing together business strategy, product thinking and research depth. My work spans R&D, manufacturing and procurement, with senior stakeholder engagement across Europe and North America.</p><p class="current-role">Lead Data Scientist, EPAM Systems<br><span>Distinguished Visiting Fellow, Loughborough University</span></p><div class="actions"><a class="button" href="#work">Enterprise work & impact ↗</a><a class="text-link" href="#feedback">Stakeholder perspectives ↓</a></div><div class="hero-proof"><a href="#recognition"><strong>Data Leader finalist</strong><span>British Data Awards · 2026</span></a><a href="{e(reach['scholar']['url'])}"><strong>{reach['scholar']['citations']:,} citations</strong><span>Google Scholar · {e(metric_date)}</span></a></div></div><div class="leadership-visual"><figure><a class="leader-panel" {viewer_link(panel['image'],panel['title'],panel['caption'])}>{media_picture(panel,eager=True)}<span class="enlarge">View panel photograph ↗</span></a><figcaption><p class="eyebrow">International speaker & panellist</p><h2>Bringing AI into<br>industry dialogue.</h2><p>IEA Wind Task 43 · Colorado, 2025<br>Panellist alongside participants from Microsoft, NREL, Siemens and OST. Pictured second from left.</p><a class="text-link" href="#speaking">Explore talks & panels →</a></figcaption></figure><a class="leader-podcast" href="https://www.youtube.com/watch?v=FXgvSQKDZzs" data-viewer="youtube" data-video-id="FXgvSQKDZzs" data-title="Explainable AI and the Power of Quiet Thinking" data-caption="Low to Grow podcast · November 2025"><span class="play-disc">▶</span><span>In conversation<strong>Explainable AI and the power of quiet thinking</strong></span></a></div></section>
<div class="recognition"><div class="wrap"><a href="#recognition">Forbes<b>30 Under 30 Europe · 2022</b></a><a href="#recognition">British Data Awards<b>Data Leader finalist · 2026</b></a><a href="#recognition">ETH Zurich<b>Aptitude colloquium · Invited expert</b></a><a href="#recognition">Green Talents<b>German government award · 2021</b></a></div></div>
{render_engagements(leadership)}
<section class="section wrap" id="work"><div class="section-heading"><div><p class="eyebrow">01 / Enterprise AI</p><h2>From ambition<br>to application.</h2></div><p>Shaping AI opportunities, building products and helping organisations use them. Work spanning R&D, manufacturing, procurement and supply.</p></div><div class="impact-grid impact-featured">{impacts}</div><p class="impact-note">Financial figures describe annual business cases assessed in evaluations. Open each figure for scope and contribution.</p>{cases}<div class="focus-list">{chips}</div><a class="text-link" href="profile.html#experience">Full experience & career history →</a></section>
{render_feedback(leadership,photos_by_id["qmul"])}
<section class="recognition-section" id="recognition"><div class="section wrap"><div class="section-heading"><div><p class="eyebrow">02 / Recognition & contribution</p><h2>Recognised across<br>industry and research.</h2></div><p>International recognition, invited academic service and contribution to the wider AI community.</p></div><div class="credential-grid">{credentials}</div>{render_quotes(spotlight)}{render_awards(spotlight,p,photos_by_id["ktp-certificate"],photos_by_id)}<div class="certification-strip"><h3>AI & leadership credentials</h3><ul>{certifications}</ul><a class="text-link" href="profile.html#skills">Explore technical skills →</a></div><div class="development-note"><p><strong>Business, product & leadership development</strong><br>Cambridge business CPD · Oxford AI Programme · Professional Agile Leadership · AI for Product Management</p><a class="text-link" href="profile.html#cpd">Courses & professional development →</a></div></div></section>
<section class="section wrap" id="media"><div class="section-heading"><div><p class="eyebrow">03 / In the public conversation</p><h2>Watch. Listen.<br>Read a little deeper.</h2></div><p>Recorded talks, interviews, published perspectives and profiles. Explore the work in my own words and through the organisations that feature it.</p></div><div class="media-filters" role="group" aria-label="Filter media" hidden><button type="button" data-media-filter="all" aria-pressed="true">Everything</button><button type="button" data-media-filter="watch" aria-pressed="false">Watch & listen</button><button type="button" data-media-filter="read" aria-pressed="false">Press & writing</button><button type="button" data-media-filter="recognition" aria-pressed="false">Profiles & recognition</button></div><p id="media-count" class="metric-note" role="status" hidden></p><div class="appearance-grid">{appearances}</div><a class="text-link" href="profile.html#press">More press & media →</a></section>
<section class="research-section" id="research"><div class="section wrap"><div class="section-heading"><div><p class="eyebrow">04 / Research & authorship</p><h2>From new ideas<br>to shared knowledge.</h2></div><a class="text-link" href="research.html">All publications & PDFs →</a></div>{render_reach(reach)}<div class="research-editorial"><article class="book-feature"><a class="book-cover" href="{e(book['url'])}">{picture(book['image'])}</a><div><p class="eyebrow">{e(book['kicker'])}</p><h3>{e(book['title'])}</h3><p class="book-subtitle">{e(book['subtitle'])}</p><p>{e(book['summary'])}</p><a class="text-link" href="{e(book['url'])}">Explore at Wiley ↗</a></div></article><a class="paper-visual" href="assets/papers/glow-2026-power-line-om.pdf"><img src="assets/images/glow-2026-paper-preview.png" width="708" height="1000" loading="lazy" alt="First page of the graph-grounded multimodal agent paper"><span>Latest paper · GLOW at ISWC 2026<strong>Read the full paper ↗</strong></span></a></div>{render_library(downloads,p)}<div class="selected-pubs">{selected}</div></div></section>
<section class="section wrap" id="speaking"><div class="section-heading"><div><p class="eyebrow">05 / In the room</p><h2>A voice in enterprise AI.<br>A contributor to its future.</h2></div><p>Invited panels, executive roundtables and international talks connecting AI products, industrial operations and trustworthy innovation.</p></div>{render_forums(spotlight,p,photos_by_id)}<div class="photo-gallery">{photos}</div><div class="speaking-cta"><div><h3>Let’s talk about useful AI.</h3><p>Enterprise adoption, trustworthy systems, industrial applications and the journey from research to delivery.</p></div><a class="button" href="mailto:{e(p['email'])}">Speaking & collaboration ↗</a></div><a class="text-link" href="profile.html#talks">All talks & appearances →</a></section>
<dialog id="media-viewer" aria-labelledby="viewer-title"><div class="viewer-toolbar"><h2 id="viewer-title"></h2><button id="viewer-close" type="button" aria-label="Close media viewer">Close ×</button></div><div id="viewer-content"></div><p id="viewer-caption"></p><a id="viewer-original" href="#media">Open original ↗</a></dialog>
'''
